pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amount, address owner) public {
        vm.assume(recipient != address(this));
        vm.assume(amount > 0);
        vm.assume(owner != address(0));

        // Deploy a fresh C with the fuzzed owner
        c = new C(owner);
        vm.deal(address(c), amount);

        uint256 recipientBalanceBefore = recipient.balance;
        uint256 ownerBalanceBefore = owner.balance;

        vm.prank(owner);
        c.withdrawAll(recipient);

        // The recipient must receive the entire C balance; the owner's balance must not increase due to C's transfer
        bool recipientGotBalance = recipient.balance == recipientBalanceBefore + amount;
        bool contractEmptied = address(c).balance == 0;
        bool ownerNotPaid = owner.balance == ownerBalanceBefore;

        assertTrue(recipientGotBalance && contractEmptied && ownerNotPaid);
    }
}

