pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient, uint256 amount) public {
        // 1. Restrict to admissible domain
        vm.assume(recipient != address(this)); // recipient must differ from owner (which is this test contract)
        bound(amount, 1, address(this).balance / 2); // ensure test contract has enough to fund C

        // 2. Setup: fund C with ether
        vm.deal(address(this), amount * 2);
        vm.prank(address(this));
        (bool funded,) = address(c).call{value: amount}("");
        require(funded, "C funding failed");

        // Record recipient's balance before withdrawAll
        uint256 recipientBalanceBefore = address(recipient).balance;

        // Owner (this test contract) calls withdrawAll with fuzzed recipient
        vm.prank(address(this));
        c.withdrawAll(recipient);

        // 3. Assert: recipient's balance must increase by exactly the amount C held (which is 'amount')
        uint256 recipientBalanceAfter = address(recipient).balance;
        assertTrue(recipientBalanceAfter == recipientBalanceBefore + amount);
    }
}

